with with_windows as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, sum(amount) over (partition by account_id, merchant order by txn_time asc, id asc rows between unbounded preceding and current row) running_amount, ntile(10) over (partition by account_id, txn_type order by amount asc, id asc) amount_bucket, row_number() over (order by txn_time desc, id asc) seq_no from transactions) select date_trunc('month', txn_time) as activity_month, percentile_approx(amount, 0.5) as amount_p50, stddev_samp(amount) as amount_stddev, min(txn_time) as started_at, avg(running_amount) as avg_running_amount, count_if(txn_type = 'CREDIT') as credit_events, percentile_approx(amount_bucket, array(0.25, 0.5, 0.75)) as amount_bucket_quartiles from with_windows group by 1;
